begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "8fc01b15-5f21-5ee4-a54d-d7609ef71ffa", "feature_slug": "cs-conversations", "title": "3. Configuration Reference", "content": "### Channel Threading (per channel, in cs_channels.config)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Session timeout | Idle time before active conversation auto-closes | 24h (LINE) | Channel-dependent |\n| Threading interval | Window to reopen resolved/closed conversation | 48h (LINE), 24h (WhatsApp) | Channel-dependent |\n\n**Default intervals by channel:**\n\n| Channel | Session Timeout | Threading Interval |\n|---|---|---|\n| LINE | 24h | 48h |\n| WhatsApp | 24h | 24h |\n| Email | — | 72h |\n| Web chat | 30 min | — |\n| Voice | — (every call = new) | — |\n| Shopee/Lazada/TikTok | Platform-controlled | Platform-controlled |\n\n### Conversation Fields\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Priority | Urgency level on conversation | `urgent` | `normal` |\n| Tags | Free-form labels for categorization | `[\"refund\", \"vip\"]` | `[]` |\n| Intent | AI-detected customer intent | `refund_request` | null |\n| Custom fields | Merchant-defined structured data | `{\"order_number\": \"12345\"}` | `{}` |\n\n### Brand Configuration (cs-brand-config page)\n\nChannel-level settings (session timeouts, threading intervals, AI behavior, auto-assignment rules) are configured per brand in the **CS Brand Config** page. This is separate from individual conversation settings.", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/cs-conversations.md#L41 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "632865f1ef1e351b5b32f26d51f004d272f7b6dc56249a01302c9665223fdfa8", "truncated": false}, "is_active": true}, {"id": "1e68a78a-39ea-51dc-9d8b-bf49b376f0e5", "feature_slug": "cs-conversations", "title": "Functions — Deployed", "content": "### Pipeline (called by Inngest / edge functions)\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_api_receive_message` | API | `(p_merchant_id, p_platform_type, p_platform_user_id, p_message_content, p_message_type, p_platform_conversation_id, p_credential_id, p_display_name, p_modality, p_metadata)` | Master inbound: resolve contact + upsert conversation + insert message. Returns conversation_id, contact_id, message_id, is_new_conversation. |\n| `cs_fn_upsert_conversation` | Backend | `(p_merchant_id, p_contact_id, p_credential_id, p_platform_conversation_id, p_modality)` | Threading logic: find existing by platform_conversation_id or session timeout. Returns conversation_id, is_new. |\n| `cs_fn_insert_message` | Backend | `(p_conversation_id, p_merchant_id, p_sender_type, p_content, p_message_type, p_sender_id, p_metadata)` | Insert message + update last_message_at + log conversation event. Returns message_id. **Dedup guard:** For system/ai sender types, returns existing message_id if identical message (same conversation + sender_type + content + message_type) exists within 60s. |\n| `cs_fn_load_conversation_context` | Backend | `(p_conversation_id, p_message_limit)` | Aggregate full AI context: conversation + messages + contact + memory + ticket + brand config + guardrails + procedure. |\n| `cs_fn_resolve_conversation` | Backend | `(p_conversation_id, p_merchant_id, p_actor_type, p_actor_id)` | Set resolved, log event. Auto-resolves linked ticket if applicable. |\n| `cs_fn_save_procedure_state` | Backend | `(p_conversation_id, p_procedure_id, p_procedure_state)` | Save AOP execution state to conversation.procedure_state. |\n\n### Admin BFF (called by admin panel)\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_bff_list_conversations` | BFF | `(p_status, p_priority, p_assigned_agent_id, p_assigned_team_id, p_modality, p_search, p_limit, p_offset)` | Unified inbox: conversations + contact name + last message preview + unread count. |\n| `cs_bff_get_conversation_details` | BFF | `(p_conversation_id)` | Conversation + all messages + contact + ticket + procedure state. |\n| `cs_bff_update_conversation` | BFF | `(p_conversation_id, p_status, p_priority, p_assigned_agent_id, p_assigned_team_id, p_tags, p_intent, p_custom_fields)` | Single function for all updates. Logs events for each change. Sets resolved_at on resolution. |\n| `cs_bff_send_message` | BFF | `(p_conversation_id, p_content, p_message_type, p_metadata)` | Agent reply or internal note. Uses cs_fn_insert_message internally. |\n\n### Architecture\n\nInbound flow: Webhook edge function → `cs_api_receive_message` → emit Inngest event `cs/message.received` → `inngest-cs-serve` runs pipeline steps → `step.invoke(\"cs/agent.decide\")` routes to Render AgentKit agent → agent reasons + calls MCP tools → result returns → edge function sends reply + saves state.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Conversations.md#L113 Functions — Deployed", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "fbc240c97425c757dabeff66fffae1521b71efb6c3160eb674859ecc097c59b7", "truncated": false}, "is_active": true}, {"id": "3e034bba-2976-5ee4-bda7-c9096848bec7", "feature_slug": "cs-conversations", "title": "Core Tables", "content": "### cs_conversations\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `merchant_id` | uuid FK | |\n| `channel_id` | uuid FK → cs_channels | |\n| `customer_id` | uuid FK → cs_customers | |\n| `status` | text | `open`, `pending`, `snoozed`, `resolved`, `closed` |\n| `priority` | text | `urgent`, `high`, `normal`, `low` |\n| `assigned_agent_id` | uuid | References `admin_users.id`. Nullable. |\n| `assigned_team_id` | uuid FK → cs_teams | Nullable |\n| `tags` | text[] | |\n| `intent` | text | AI-detected intent. Nullable. |\n| `active_procedure_id` | uuid FK → cs_procedures | Which AOP is running. Nullable. |\n| `procedure_state` | jsonb | Current step, collected data, tool results. Nullable. |\n| `platform_conversation_id` | text | Shopee/Lazada native thread ID |\n| `custom_fields` | jsonb | |\n| `last_message_at` | timestamptz | |\n| `resolved_at` | timestamptz | |\n| `created_at` | timestamptz | |\n\n### cs_messages\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `conversation_id` | uuid FK → cs_conversations | |\n| `sender_type` | text | `customer`, `agent`, `ai`, `system` |\n| `sender_id` | uuid | `admin_users.id` for agents. Null for customer/ai/system. |\n| `content` | text | Message body |\n| `message_type` | text | `text`, `image`, `product_card`, `order_card`, `voice_transcript`, `file`, `note` |\n| `metadata` | jsonb | platform_message_id, delivery_status, attachments, card_data |\n| `created_at` | timestamptz | |\n\n`message_type = ''note''` = internal notes (invisible to customer).\n\n### cs_conversation_events\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `conversation_id` | uuid FK → cs_conversations | |\n| `event_type` | text | `created`, `message_received`, `assigned`, `status_changed`, `action_executed`, `escalated`, `resolved`, `procedure_step_completed`, `csat_submitted` |\n| `actor_type` | text | `customer`, `agent`, `ai`, `system`, `rule` |\n| `actor_id` | uuid | |\n| `event_data` | jsonb | Full payload |\n| `created_at` | timestamptz | |\n\nINSERT-only, never updated. Audit trail + analytics source.\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Conversations.md#L8 Core Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e11c4db2d39c2c8e1f1501c2bd6f4317794cc2588fbaa55df75278cf57a784fa", "truncated": false}, "is_active": true}, {"id": "f93cd6eb-efca-5de5-9fb5-0747170867a8", "feature_slug": "cs-conversations", "title": "2. Key Concepts", "content": "**Conversation** — A message thread between a customer and the business on a specific channel. Contains messages, status, priority, assignment, and optional procedure state. One customer can have many conversations over time, but typically only one active conversation per channel at a time. Example: Customer sends \"Where is my order?\" on LINE → a conversation is created.\n\n**Message** — A single entry in a conversation thread. Has a sender type, content, and message type. Messages are append-only — they cannot be edited or deleted.\n\n**Sender Type** — Who sent the message: `customer` (end user on their channel), `agent` (human CS agent), `ai` (AI agent), `system` (automated notifications like status changes or assignment events).\n\n**Message Type** — The content format: `text` (plain text), `image` (photo attachment), `product_card` (marketplace product), `order_card` (order details), `voice_transcript` (transcribed voice message), `file` (document attachment), `note` (internal — invisible to customer).\n\n**Internal Note** — A message with `message_type = ''note''`. Visible only to agents in the inbox. Never delivered to the customer''s channel. Used for handoff context, investigation notes, or team coordination.\n\n**Conversation Status** — The lifecycle state: `open` (active, needs attention), `pending` (awaiting action), `snoozed` (temporarily hidden, resurfaces at set time), `resolved` (issue addressed), `closed` (fully complete). See Business Rules for valid transitions.\n\n**Priority** — Urgency level: `urgent`, `high`, `normal`, `low`. Displayed as a color strip on the conversation list item (red for urgent, yellow for high). Can be set manually or by routing rules.\n\n**Assignment** — Which agent or team is responsible for a conversation. Can be assigned to an individual agent (`assigned_agent_id`) or a team (`assigned_team_id`). Unassigned conversations appear in the \"Unassigned\" inbox view.\n\n**Threading Interval** — The time window after a conversation is resolved/closed during which a new message from the same customer on the same channel reopens the existing conversation instead of creating a new one. Configurable per channel. Example: LINE threading interval = 48h. Customer messages 24h after resolution → same conversation reopens. Customer messages 72h after → new conversation.\n\n**Session Timeout** — For active (open/pending) conversations, the maximum idle time before the system closes the conversation as inactive and creates a new one on the next message. Example: Web chat session timeout = 30 minutes.\n\n**Conversation Event** — An immutable audit log entry recording what happened: `created`, `message_received`, `assigned`, `status_changed`, `action_executed`, `escalated`, `resolved`, `procedure_step_completed`, `csat_submitted`. INSERT-only, never updated. Each event records the actor type (`customer`, `agent`, `ai`, `system`, `rule`) and a JSON payload.\n\n**Procedure State** — When an AOP (automated operating procedure) is active on a conversation, the current step, collected data, and tool results are stored as JSON in `procedure_state`. See CS Procedures guide.\n\n**Inbox View** — A filtered subset of conversations. Built-in views: My Open, Unassigned, All Open, Overdue, Resolved. Each view shows a badge count.\n\n**Content Panel** — A slide-out panel within the chat thread for accessing knowledge base articles or canned responses without leaving the conversation.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/cs-conversations.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ec76deba02b7665ce75fe9d1b0e43bde9d777a3765621e59dfe11f8d0b6365b6", "truncated": false}, "is_active": true}, {"id": "100804ec-26c2-5453-8104-d6c0c789565f", "feature_slug": "cs-conversations", "title": "1. Overview", "content": "Conversations are the core communication layer of the CS module — every customer interaction across every channel flows through them. When a customer sends a message on LINE, WhatsApp, Facebook, Shopee, or any connected channel, the system creates (or reopens) a conversation and routes it into a unified inbox where agents and AI respond.\n\nThe inbox is a 3-panel workspace: conversation list on the left, chat thread in the center, customer details on the right. Agents see all channels in one place — no switching between Shopee chat, LINE OA, and WhatsApp Business. Messages from the customer arrive in real time; agents (or AI) reply from the same thread. The system tracks the full lifecycle from first message through resolution, logging every status change, assignment, and internal note as an immutable event trail.\n\nTwo design decisions shape how conversations work: (1) **threading logic** — configurable per-channel rules that determine when a new message continues an existing conversation vs. creates a new one, preventing fragmented customer histories; (2) **AI-first pipeline** — inbound messages flow through an AI agent that can resolve simple queries autonomously, activate procedures (AOPs), or escalate to human agents, all within the same conversation thread.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/cs-conversations.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f268a23cfca1f607c1cea413e6792c7bb9ffbad9f00468d445c7c9b06a8beb34", "truncated": false}, "is_active": true}, {"id": "82fee3b4-b808-50ef-9f31-30c2b7e0de3b", "feature_slug": "cs-conversations", "title": "8. Related Features", "content": "| Feature | Connection to Conversations |\n|---|---|\n| CS Knowledge Base | AI agent retrieves articles to answer customer questions within conversations. Agents access via Content Panel. See `CS_Knowledge_Base.md`. |\n| CS Channels | Each conversation is tied to a channel (LINE, Shopee, etc.). Channel config controls threading intervals and session timeouts. See `CS_Channels.md`. |\n| CS Procedures (AOPs) | Active procedure state is stored on the conversation. AOP steps execute within the conversation thread. See `CS_Procedures.md`. |\n| CS Customers | Conversations are linked to a customer profile. Multiple conversations across channels are unified under one customer. See `CS_Channels.md` (customers section). |\n| CS Teams | Conversations can be assigned to teams for group routing. See CS Teams configuration. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/cs-conversations.md#L260 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "876660b99cf16cb899b75371aef4c8c554735bd20a95831d105d613615972715", "truncated": false}, "is_active": true}, {"id": "79f82ac4-c2d3-50c3-a248-3e9a583bedfe", "feature_slug": "cs-conversations", "title": "CS Conversations Domain Reference", "content": "**Keywords:** conversation, message, inbox, chat, reply, assign, resolve, close, reopen, ticket, priority, snoozed, pending, open, cs_conversations, cs_messages, cs_conversation_events, sender_type, message_type, note, internal_note, procedure_state\n**Source:** `CS_Conversations.md`\n**Tables:** `cs_conversations`, `cs_messages`, `cs_conversation_events`\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_conversations` | BFF | Get conversation list for inbox |\n| `cs_bff_get_conversation_detail` | BFF | Get single conversation with messages and events |\n| `cs_bff_assign_conversation` | BFF | Assign conversation to agent or team |\n| `cs_bff_update_conversation_status` | BFF | Change conversation status |\n| `cs_fn_upsert_conversation` | Backend | Create or update conversation from webhook |\n| `cs_fn_insert_message` | Backend | Insert message and update timestamps |\n| `cs_fn_log_event` | Backend | Log a conversation event |\n**Key Business Rules (summary):**\n- Status lifecycle: `open` → `pending` → `snoozed` → `resolved` → `closed` (reopen on new message)\n- One active conversation per customer per channel at a time\n- Threading interval per channel determines new vs. existing conversation\n- Internal notes (`message_type = ''note''`) are never sent to the customer\n- Conversation events are append-only (INSERT-only, never updated)\n- `procedure_state` tracks active AOP step for UI display", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-conversations.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b7b1e6df4f2f7252bad00ff1def6c65c238c832de11d027a63687d07f046755d", "truncated": false}, "is_active": true}, {"id": "b297f7a8-3655-5cf3-a262-b912a5557cdc", "feature_slug": "cs-conversations", "title": "6c. For Testers", "content": "**Status transitions to verify:**\n\n| From | To | Trigger |\n|---|---|---|\n| (none) | Open | New inbound message creates conversation |\n| Open | Pending | Agent or system sets pending |\n| Open/Pending | Snoozed | Agent snoozes with a future time |\n| Open/Pending | Resolved | Agent clicks Resolve (or AI resolves) |\n| Resolved | Closed | Auto-close after configured period |\n| Resolved/Closed | Open | Customer sends new message within threading interval |\n| (none) | Open | Customer sends message after threading interval (new conversation) |\n\n**Threading logic assertions:**\n\n- ASSERT: Message within session timeout on active conversation → appended to same conversation, no new conversation created\n- ASSERT: Message after session timeout on active conversation → old conversation closed as inactive, new conversation created\n- ASSERT: Message within threading interval on resolved conversation → conversation reopens to Open status\n- ASSERT: Message after threading interval on resolved conversation → new conversation created\n- ASSERT: Marketplace channels (Shopee, Lazada, TikTok) → follow platform''s own threading, mapped 1:1 by `platform_conversation_id`\n- ASSERT: Voice calls always create a new conversation\n\n**Message handling assertions:**\n\n- ASSERT: Internal note (`message_type = ''note''`) is never delivered to customer''s channel\n- ASSERT: `cs_fn_insert_message` dedup guard → identical message (same conversation + sender_type + content + message_type) within 60s returns existing message_id instead of creating duplicate\n- ASSERT: Every status change, assignment, and message creates a `cs_conversation_events` record\n- ASSERT: Events are INSERT-only — no UPDATE or DELETE on `cs_conversation_events`\n\n**Config → expected behavior:**\n\n| Config | Expected Behavior |\n|---|---|\n| LINE threading_interval = 48h, customer messages 24h after resolve | Same conversation reopens |\n| LINE threading_interval = 48h, customer messages 72h after resolve | New conversation created |\n| Web chat session_timeout = 30min, idle for 45min then new message | Old conversation closed, new one created |\n| Priority = urgent | Red color strip on conversation list item |\n| Conversation unassigned | Appears in \"Unassigned\" inbox view |\n| Agent sends note | Note visible in thread, not delivered to customer channel |\n\n**Cross-feature scenarios:**\n- Conversation with active procedure → `procedure_state` updates on each AOP step\n- AI resolves conversation → `cs_conversation_events` records `resolved` with `actor_type = ''ai''`\n- Customer contacts on Shopee AND LINE → two separate conversations, but linked under one `cs_customers` profile\n- Agent creates ticket from conversation → ticket linked to `conversation_id`", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/cs-conversations.md#L158 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5a7db880e79f0a835dbca40dc4f8d9c4f7537d06c5f9f4a6acea6141d8cdc1ee", "truncated": false}, "is_active": true}, {"id": "17943e05-36d7-5dd8-874d-a6252830b2cc", "feature_slug": "cs-conversations", "title": "5. Customer Experience", "content": "The customer interacts entirely through their own messaging channel. There is no dedicated \"CS app\" — the experience is native to LINE, WhatsApp, Facebook Messenger, Shopee Chat, etc.\n\n**Channel map:**\n\n| Channel | Customer Interface | Message Types Supported |\n|---|---|---|\n| LINE | LINE app chat | Text, image, file |\n| WhatsApp | WhatsApp chat | Text, image, file |\n| Facebook/Instagram | Messenger / DM | Text, image |\n| Shopee/Lazada/TikTok | Platform chat window | Text, image, product card, order card |\n| Email | Email thread | Text, file |\n| Web chat | Embedded widget on website | Text, image, file |\n| Voice | Phone call → transcribed | Voice transcript |\n\n### 5a. Customer Sends a Message\n\n1. Customer sends a message on their channel (e.g., types \"Where is my order?\" in LINE)\n2. System receives webhook → resolves customer identity → creates or reopens a conversation\n3. AI agent evaluates the message, may respond automatically (from knowledge base) or activate a procedure\n4. If AI cannot resolve, conversation is assigned to a human agent\n5. Customer sees the reply in their channel — indistinguishable from a human or AI sender (no \"AI\" label on customer side)\n\n### 5b. Customer Receives a Response\n\n1. Agent or AI reply appears as a new message in the customer''s chat\n2. Rich content (product cards, order cards) renders natively on supported platforms\n3. Customer can continue the conversation by sending another message\n\n### 5c. Conversation Ends\n\n1. When the issue is resolved, the conversation moves to resolved status\n2. Customer may receive a CSAT survey (if configured)\n3. If customer messages again within the threading interval → same conversation reopens\n4. If customer messages after the threading interval → new conversation is created with fresh context", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/cs-conversations.md#L121 5. Customer Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a51f525e83bb95321cb9bcbfe3d842a65749ed6f0ecb1cfc7197abb0fdad436b", "truncated": false}, "is_active": true}, {"id": "2949c9a7-5233-5974-8791-6ad2987d166d", "feature_slug": "cs-conversations", "title": "6b. For Marketing", "content": "**Customer engagement data available from conversations:**\n- Volume by channel (which channels customers prefer)\n- Peak contact hours and response time trends\n- Top intents and topics (what customers ask about most)\n- Resolution patterns (AI-resolved vs. human-resolved)\n- CSAT scores post-resolution\n\n**Use cases:** Channel preference data informs where to invest in customer communication. Intent analysis reveals product/service pain points before they become widespread issues. Conversation volume spikes correlate with campaign launches or service disruptions.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/cs-conversations.md#L158 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a41fbd1d89be71c70d63c75cc0ec4bcbb609b5657de3d2a0485c44ce3e37f1d9", "truncated": false}, "is_active": true}, {"id": "198599ed-2808-52b6-a4fd-eda275c1d533", "feature_slug": "cs-knowledge-base", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Knowledge Hub | `/cs-knowledge` | `cs_bff_get_knowledge_overview()`, `cs_bff_get_knowledge_sources()`, `cs_bff_get_knowledge_articles()` |\n| Article List | `/cs-knowledge/articles` | `cs_bff_get_knowledge_articles(filters)` |\n| Article Editor (create) | `/cs-knowledge/articles/new` | Empty form |\n| Article Editor (edit) | `/cs-knowledge/articles/{id}` | `cs_bff_get_knowledge_article(id)` |\n| Source List | `/cs-knowledge/sources` | `cs_bff_get_knowledge_sources()` |\n| Source Editor (create) | `/cs-knowledge/sources/new` | Empty form |\n| Source Editor (edit) | `/cs-knowledge/sources/{id}` | `cs_bff_get_knowledge_source(id)` |\n| Custom Answer List | `/cs-knowledge/custom-answers` | `cs_bff_get_knowledge_articles(is_custom_answer=true)` |\n| Custom Answer Editor (create) | `/cs-knowledge/custom-answers/new` | Empty form |\n| Custom Answer Editor (edit) | `/cs-knowledge/custom-answers/{id}` | `cs_bff_get_knowledge_article(id)` |\n\n### 4a. Knowledge Hub Dashboard\n\n1. **Knowledge Hub** is the landing page — shows four stat cards: Sources count, Articles count, Custom Answers count, Active/Draft breakdown\n2. Below stats: **Knowledge Sources** card listing each source with name, type badge, sync status badge, article count, and last synced date\n3. Warning banner appears if any sources have `sync_status = failed`\n4. Two side-by-side cards: **Recent Articles** (5 most recent non-custom-answer articles) and **Custom Answers** (5 most recent)\n5. Primary action button: **\"New article\"**. Secondary actions: **\"Add source\"**, **\"New custom answer\"**\n\n### 4b. Create an Article\n\n1. From **Knowledge Hub**, click **\"New article\"** (or from **Article List**, click create)\n2. **Article Editor** opens — main area: Title (required) + rich-text Content editor\n3. Sidebar: Status dropdown (draft/active/archived), Category dropdown, Language dropdown\n4. Click **\"Publish article\"** to save\n5. On save: triggers embedding pipeline automatically if status is `active`\n\n### 4c. Manage Articles\n\n1. **Article List** displays articles with title, category badge, status badge\n2. Filter by: search text, category, source, status\n3. Click any article row → opens **Article Editor** in edit mode\n4. Edit mode shows additional Details card: source type, created date, updated date\n5. Secondary action toggles between \"Activate\" and \"Revert to draft\"\n6. Delete available from the list view\n\n### 4d. Manage Sources\n\n1. **Source List** shows all sources with name, type badge (Document/Website/Catalog/API/Manual), sync status badge (Synced/Syncing/Pending/Failed), article count, and last synced timestamp\n2. Click **\"Add source\"** → **Source Editor**: name (required), source type dropdown, config JSONB (type-specific — URL for website sources, file path for documents), active toggle\n3. Each source can be individually synced via **trigger sync** action\n4. Failed sources show in the **Knowledge Hub** warning banner with source names and \"View sources\" link\n5. Deactivating a source (`is_active = false`) stops future syncs but does not remove existing articles\n\n### 4e. Manage Custom Answers\n\n1. **Custom Answer List** shows answers with title, trigger pattern count, and priority value\n2. Create flow similar to articles but with additional fields: question patterns (text array of trigger phrases), priority (integer, higher = checked first)\n3. Custom answers require at least one question pattern (BFF validation rejects empty arrays)\n4. Edit mode shows same fields as creation, pre-populated from stored data\n\n### 4f. Common Admin Mistakes\n\n- Creating articles but leaving them as `draft` → AI cannot find them, support quality drops\n- Setting up a source but not triggering initial sync → zero articles imported\n- Writing custom answers with overly broad patterns (e.g., `\"order\"`) → matches unrelated questions\n- Writing custom answers with overly narrow patterns → customers phrase questions differently, answer never triggers\n- Archiving articles still referenced by active procedures → procedure context becomes incomplete\n- Ignoring failed source sync warnings → knowledge becomes stale without admin realizing", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L68 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8cce89e1f102c18a386aa0850a23910959f8f2ea19ed8cf1f711ffd250491b00", "truncated": false}, "is_active": true}, {"id": "1d90c79c-d3eb-52ae-80f1-274c439910a9", "feature_slug": "cs-knowledge-base", "title": "7. Business Rules", "content": "**Rule:** Only active articles are searchable. Draft and archived articles exist in the database but are excluded from both semantic search and text search.\n**Example:** Admin creates an article about a new return policy but keeps it as `draft` while legal reviews. AI and agents cannot find it until the admin changes status to `active`.\n\n**Rule:** Custom answers are checked before AI reasoning. The system runs `cs_fn_match_custom_answer` first; only if it returns null does the semantic search + LLM pipeline execute.\n**Example:** Custom answer exists for \"return policy\" with priority 10. Customer asks \"What''s your return policy?\" → exact custom answer content returned, AI does not generate its own response.\n\n**Rule:** Custom answer matching uses case-insensitive substring matching (LIKE), not semantic similarity. The customer''s message must contain the pattern as a substring.\n**Example:** Pattern `\"return policy\"` matches \"What is your return policy?\" but does NOT match \"How do I send something back?\" (even though semantically similar).\n\n**Rule:** On article update, the embedding pipeline deletes all existing chunks and regenerates from the new content. There is no incremental update.\n**Example:** Admin edits a 3-chunk article, adding a paragraph. All 3 old chunks are deleted. The updated content is re-chunked (now 4 chunks) and re-embedded.\n\n**Rule:** Knowledge is merchant-scoped. RLS on `merchant_id` ensures Brand A''s articles, sources, and embeddings are invisible to Brand B. This applies to all search functions and admin BFFs.\n**Example:** Brand A has 200 articles about skincare. Brand B searching for \"moisturizer\" returns zero results from Brand A''s content.\n\n**Rule:** Source `article_count` tracks how many articles were created from that source. Deleting a source does not automatically delete its articles (articles may have been manually edited after sync).\n**Example:** Admin deletes the \"Product FAQ Website\" source. The 50 articles it created remain in the knowledge base.\n\n**Rule:** Custom answers require at least one question pattern. The BFF validates this on save — an empty `question_patterns` array is rejected.\n**Example:** Admin tries to save a custom answer with no patterns → error returned, save blocked.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L237 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7143e4416a9f3bf3c4e6ceb1f7985b0af8ba520a91838d914fda9a238267f1bc", "truncated": false}, "is_active": true}, {"id": "a756ebbd-3c20-5136-8280-197a46b2fabe", "feature_slug": "cs-knowledge-base", "title": "3. Configuration Reference", "content": "### Article Settings\n\n| Setting | What it controls | Options / Example | Default |\n|---|---|---|---|\n| Title | Article display name, searched by text search | \"How to Return a Product\" | Required |\n| Content | Rich-text body, chunked and embedded for AI search | HTML content | Empty |\n| Status | Searchability by AI and agents | `draft`, `active`, `archived` | `draft` |\n| Category | Organizational grouping and filter | `products`, `policies`, `shipping`, `returns`, `faq` | None |\n| Language | Content language tag | `en`, `th`, `ja`, `zh` | `en` |\n\n### Custom Answer Settings\n\n| Setting | What it controls | Options / Example | Default |\n|---|---|---|---|\n| Is Custom Answer | Marks article as exact-response override | `true` / `false` | `false` |\n| Question Patterns | Trigger phrases that activate this answer | `[\"return policy\", \"how to return\"]` | `[]` |\n| Priority | Ordering when multiple custom answers match | Higher = checked first | `0` |\n\n### Source Settings\n\n| Setting | What it controls | Options / Example | Default |\n|---|---|---|---|\n| Name | Display label for the source | \"Product FAQ Website\" | Required |\n| Source Type | Content ingestion method | `document`, `url`, `catalog`, `api`, `manual` | Required |\n| Config | Type-specific configuration (JSONB) | URL, credentials, sync schedule | `{}` |\n| Is Active | Whether sync is enabled | `true` / `false` | `true` |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L39 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "74e7faea2ff35a1d571c0df4e017fe026930d952da7c6fa9315711cc335e55a1", "truncated": false}, "is_active": true}, {"id": "6ced73c2-9196-504d-9100-e4652ec283ab", "feature_slug": "cs-knowledge-base", "title": "Core Tables", "content": "### cs_knowledge_articles\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `merchant_id` | uuid FK | |\n| `title` | text | |\n| `content` | text | Full article body |\n| `category` | text | `products`, `policies`, `shipping`, `returns`, `faq` |\n| `language` | text | |\n| `source_type` | text | `document`, `url`, `catalog`, `manual` |\n| `source_url` | text | Nullable |\n| `status` | text | `active`, `draft`, `archived` |\n| `is_custom_answer` | boolean | default false |\n| `question_patterns` | text[] | For custom answers — example phrasings |\n| `priority` | int | Higher = checked first |\n| `created_at` | timestamptz | |\n| `updated_at` | timestamptz | |\n\n### cs_knowledge_embeddings\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `article_id` | uuid FK → cs_knowledge_articles | |\n| `chunk_index` | int | Position in article |\n| `chunk_text` | text | ~500 token chunk |\n| `embedding` | vector(1536) | pgvector |\n| `created_at` | timestamptz | |\n\nNever manually written. Auto-generated.\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Knowledge_Base.md#L8 Core Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5ac0f3e435dc06d14d779882810d25b4c75271303de72de4dc2e1bd28c93eba1", "truncated": false}, "is_active": true}, {"id": "fb42abbd-3c70-5701-b519-947798a9101d", "feature_slug": "cs-knowledge-base", "title": "Functions — Deployed", "content": "### Pipeline\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_fn_search_knowledge` | Backend | `(p_merchant_id, p_query_embedding vector(1536), p_limit, p_category, p_similarity_threshold)` | pgvector cosine similarity search. Accepts pre-computed embedding vector. Returns top K chunks with article metadata. |\n| `cs_fn_match_custom_answer` | Backend | `(p_merchant_id, p_message_text)` | Check message text against custom answer question_patterns using LIKE matching. Returns matching article content or null. |\n\n### Admin BFF\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_bff_upsert_knowledge_article` | BFF | `(p_article_id, p_title, p_content, p_category, p_language, p_source_id, p_source_type, p_source_url, p_status, p_is_custom_answer, p_question_patterns, p_priority)` | Create/update article. Validates custom answers require question_patterns. |\n\n### Direct CRUD (Supabase client + RLS)\n\n- List articles: direct table read with filters\n- Get single article: direct table read\n- Delete article: direct delete (embeddings cascade)\n- List/upsert knowledge sources: direct table access\n\n### Embedding pipeline\n\nEmbedding generation is NOT a DB function — it''s an edge function (`embed-knowledge`) triggered via pgmq when articles are inserted/updated. Calls OpenAI embedding API, writes vectors to cs_knowledge_embeddings.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Knowledge_Base.md#L91 Functions — Deployed", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d958a1368a52eee6cc382924aaf24009eb237769a6eb9b51473e387bfe1751a0", "truncated": false}, "is_active": true}, {"id": "1513189d-1d53-5a91-80c1-e43b4582269b", "feature_slug": "cs-knowledge-base", "title": "2. Key Concepts", "content": "**Knowledge Article** — A unit of content in the knowledge base: a title, rich-text body, category, language, and status. Articles are the atomic unit that gets embedded and searched. Example: \"Return Policy — Thailand\" with content explaining the 7-day return window.\n\n**Knowledge Source** — A content feed that produces articles. Sources have a type (document, website, catalog, API, manual), sync configuration, and sync status. Example: A \"Product FAQ Website\" source of type `url` that crawls the brand''s FAQ page.\n\n**Source Type** — How content enters the system. Five types: `document` (uploaded PDF/DOCX/TXT/CSV), `url` (website crawler), `catalog` (product catalog sync from Shopee/Lazada/Shopify), `api` (external CMS connector), `manual` (hand-written in admin editor).\n\n**Sync Status** — Tracks whether a source''s content is current. Values: `pending` (never synced), `syncing` (sync in progress), `synced` (up to date), `failed` (last sync errored). Each source tracks `last_synced_at` and `article_count`.\n\n**Category** — Organizational grouping for articles. Default categories: `products`, `policies`, `shipping`, `returns`, `faq`. Displayed as filter chips in the admin article list.\n\n**Article Status** — Lifecycle state controlling searchability. Values: `draft` (being written, not searchable), `active` (searchable by AI and agents), `archived` (hidden from search, retained for history). Default for new articles: `draft`.\n\n**Embedding** — A 1536-dimensional vector representation of a text chunk, generated by OpenAI''s text-embedding model. Stored in pgvector. Used for semantic similarity search — finding content by meaning rather than exact keyword match.\n\n**Chunk** — A ~500-token segment of an article''s content. Long articles are split into multiple chunks, each independently embedded. The `chunk_index` tracks ordering within the article.\n\n**Semantic Search** — How the AI agent finds relevant knowledge. The customer''s question is embedded into a vector, then compared against all stored chunk embeddings using cosine similarity. Returns the top K most relevant chunks above a similarity threshold (default 0.7).\n\n**Text Search** — How human agents find knowledge during conversations. Uses text matching (ILIKE) against article titles and content. Simpler than semantic search but works without embeddings.\n\n**Custom Answer** — An article with `is_custom_answer = true` that includes `question_patterns` (trigger phrases). When a customer message contains any trigger phrase (case-insensitive LIKE match), the custom answer''s content is used directly instead of AI-generated reasoning. Higher `priority` values are checked first.\n\n**Question Patterns** — A text array on custom answer articles. Each entry is a phrase that, when found in a customer message (substring match, case-insensitive), triggers the custom answer. Example: `[\"return policy\", \"how to return\", \"refund process\"]`.\n\n**Embedding Pipeline** — The automatic process that converts article text into searchable vectors. Triggered on article insert or update via DB trigger → pgmq queue → pg_cron → Edge Function (`embed-knowledge`) → OpenAI API → pgvector storage. On update, old chunks are deleted and regenerated.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "34c34ae58c8e65a38a49104fa833f3481fa158aa71ae77fdfc8b289b2f306b26", "truncated": false}, "is_active": true}, {"id": "c561b0f1-d066-5a31-8986-6deb170d220d", "feature_slug": "cs-knowledge-base", "title": "1. Overview", "content": "The Knowledge Base is the central content repository for the CS module''s AI agent. It stores articles — product descriptions, policies, FAQs, how-to guides — that both the AI agent and human agents reference when answering customer questions. Without knowledge base content, the AI has nothing to ground its responses on and cannot answer domain-specific questions.\n\nContent enters the knowledge base through two paths: manually authored articles (written directly in the admin editor) and synced sources (documents, website crawls, catalog imports, API feeds). When an article is created or updated, an automatic embedding pipeline chunks the text into ~500-token segments, generates vector embeddings via OpenAI, and stores them in pgvector. This enables the AI agent to perform semantic search — finding relevant knowledge even when the customer''s phrasing doesn''t match the article''s exact wording.\n\nA separate feature, Custom Answers, lets admins define exact responses for specific question patterns. These override AI-generated responses and are checked before the AI reasons over retrieved knowledge. Custom answers are stored as a special type of knowledge article (`is_custom_answer = true`) with trigger patterns that match against incoming messages.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "449a7d59f43b06d2d562f216e57df5deacd437e9200da578c013221a35d63099", "truncated": false}, "is_active": true}, {"id": "2b363379-778c-542d-bc80-b7d541581189", "feature_slug": "cs-knowledge-base", "title": "8. Related Features", "content": "| Feature | Connection to Knowledge Base |\n|---|---|\n| CS Conversations | Human agents search knowledge from the conversation sidebar via `cs_bff_search_conversation_knowledge`. AI agent retrieves knowledge during response generation. |\n| CS Procedures (AOPs) | Procedures can reference knowledge articles as context. The AI loads relevant knowledge when executing procedure steps. |\n| CS Brand Config | Brand voice and guidance rules shape how the AI uses retrieved knowledge in its responses. |\n| CS Customers | Customer context (memory, profile) combined with retrieved knowledge enables personalized AI responses. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L260 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "52a0dc7f14bc3ba9e170db7a2c03d3ab1524e265029eff38659467cd53177bd7", "truncated": false}, "is_active": true}, {"id": "0dc33304-f952-548f-ba88-884788bcef7e", "feature_slug": "cs-knowledge-base", "title": "CS Knowledge Base Domain Reference", "content": "**Keywords:** knowledge, article, embedding, faq, semantic_search, rag, vector, pgvector, chunk, cs_knowledge_articles, cs_knowledge_embeddings, source_type, search_knowledge_articles\n**Source:** `CS_Knowledge_Base.md`\n**Tables:** `cs_knowledge_articles`, `cs_knowledge_embeddings`\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_knowledge_articles` | BFF | List articles with filtering (admin) |\n| `cs_bff_upsert_knowledge_article` | BFF | Create or update article (triggers re-embedding) |\n| `cs_bff_get_knowledge_article` | BFF | Get single article |\n| `cs_bff_get_knowledge_categories` | BFF | List distinct categories |\n| `cs_bff_get_knowledge_overview` | BFF | Dashboard summary stats |\n| `cs_bff_get_knowledge_sources` | BFF | List knowledge sources |\n| `cs_bff_upsert_knowledge_source` | BFF | Create/update knowledge source |\n| `cs_bff_delete_knowledge_article` | BFF | Delete article |\n| `cs_bff_delete_knowledge_source` | BFF | Delete knowledge source |\n| `cs_fn_search_knowledge` | Backend | pgvector semantic search for AI — accepts embedding vector, returns top K chunks |\n| `cs_fn_search_knowledge_articles` | Backend | Text-based search for human agents during conversations — title/content/category matching |\n| `cs_fn_match_custom_answer` | Backend | **Deprecated** — replaced by `cs_fn_match_resource` on `resource_content` |\n**Key Business Rules (summary):**\n- Knowledge = reference material for both AI and human agents (never sent directly to customer)\n- Custom answers migrated to `resource_content` as quick_replies (see Resource Content domain)\n- `cs_fn_match_custom_answer` deprecated — use `cs_fn_match_resource` instead\n- AI uses `cs_fn_search_knowledge` (embedding-based semantic search)\n- Human agents use `cs_fn_search_knowledge_articles` (text-based search during conversations)\n- Embedding pipeline: article change → trigger → pgmq → edge function → OpenAI → pgvector\n- Only `status = ''active''` articles are searchable\n- Article updates trigger automatic re-embedding (old chunks deleted, new created)", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-knowledge-base.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f50085614b4f99b48032a8b765df8942fb5279178c09a453420abf09e8a31b16", "truncated": false}, "is_active": true}, {"id": "056930b0-5627-513e-bc8a-5902a3620c5f", "feature_slug": "cs-knowledge-base", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Article `status = draft` | Not returned by semantic search or text search |\n| Article `status = active` | Returned by both search types |\n| Article `status = archived` | Not returned by search |\n| Custom answer with patterns `[\"refund\"]`, `status = active` | Customer message \"How do I get a refund?\" → custom answer content used directly |\n| Custom answer with `status = draft` | Not matched even if patterns match |\n| Two custom answers match, priority 10 vs priority 5 | Priority 10 answer wins |\n| Source `sync_status = failed` | Warning banner on Knowledge Hub |\n| Source `is_active = false` | Source not synced, existing articles remain |\n| Article updated | Old embeddings deleted, new embeddings generated |\n| Article deleted | Associated embeddings cascade-deleted |\n\n**Embedding pipeline assertions:**\n\n- ASSERT: New active article → within seconds, `cs_knowledge_embeddings` rows exist for that `article_id`\n- ASSERT: Article content updated → old chunks deleted, new chunks with updated content created\n- ASSERT: Article deleted → all `cs_knowledge_embeddings` with that `article_id` are gone\n- ASSERT: Draft article → no embeddings generated (only active articles are embedded)\n- ASSERT: `cs_fn_search_knowledge` with `p_similarity_threshold = 0.7` → only chunks with cosine similarity >= 0.7 returned\n\n**Custom answer matching assertions:**\n\n- ASSERT: `cs_fn_match_custom_answer` uses case-insensitive substring matching (LIKE `%pattern%`)\n- ASSERT: Only `is_custom_answer = true` AND `status = ''active''` articles are checked\n- ASSERT: Highest `priority` match wins when multiple patterns match\n- ASSERT: Returns `NULL` when no patterns match\n\n**Status model (single track):**\n\n| Field | Values | Transition | Effect |\n|---|---|---|---|\n| `status` | `draft` → `active` | Admin activates | Article becomes searchable, embedding pipeline runs |\n| `status` | `active` → `archived` | Admin archives | Article excluded from search, embeddings retained |\n| `status` | `active` → `draft` | Admin reverts to draft | Article excluded from search |\n| `status` | `archived` → `active` | Admin reactivates | Article searchable again |\n\n**Cross-feature scenarios:**\n\n- Human agent searches knowledge during conversation → results are merchant-scoped (RLS on `merchant_id`)\n- Brand A''s knowledge never appears in Brand B''s search results (multi-tenant isolation)\n- Bulk status update (multiple articles → active/draft) via `cs_bff_bulk_update_articles`\n- Source sync produces articles → articles automatically get embeddings via pipeline\n- Custom answer with empty `question_patterns` → BFF validation rejects save\n- Semantic search with no matching content (similarity below threshold for all chunks) → AI falls back to general reasoning or escalates", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L162 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "44741aab49f90d4d03d5add1c8aa77a89cadc1da76092710ef9b2c1c1f72874d", "truncated": false}, "is_active": true}, {"id": "7dbaa0bf-d0a0-560d-97f2-224af01b46ff", "feature_slug": "cs-knowledge-base", "title": "5. Agent / AI Experience", "content": "This feature has no direct customer-facing UI. Knowledge is consumed by AI and human agents as reference material.\n\n**Route map (agent-facing, within CS Inbox):**\n\n| Context | Access point | Data source |\n|---|---|---|\n| AI semantic search | Automatic during AI response generation | `cs_fn_search_knowledge(embedding, limit, category, threshold)` |\n| AI custom answer check | Automatic before AI generates response | `cs_fn_match_custom_answer(merchant_id, message_text)` |\n| Human agent sidebar search | Search box in conversation sidebar | `cs_bff_search_conversation_knowledge(search_text, category, limit)` |\n\n### 5a. AI Agent Uses Knowledge\n\n1. Customer sends a message\n2. System checks for custom answer match first: `cs_fn_match_custom_answer` runs LIKE matching against active custom answers'' `question_patterns`, ordered by `priority` DESC\n3. If custom answer matches → its content is used directly as the response (no AI reasoning)\n4. If no custom answer matches → customer message is embedded via OpenAI → `cs_fn_search_knowledge` runs cosine similarity against `cs_knowledge_embeddings` → top K chunks (above 0.7 threshold) returned → injected into LLM prompt as context → AI generates grounded response\n\n### 5b. Human Agent Uses Knowledge\n\n1. During a conversation, agent sees a search box in the sidebar\n2. Agent types a query → `cs_bff_search_conversation_knowledge` performs text search against active articles\n3. Matching articles displayed with title and content preview\n4. Agent reads the article to inform their response to the customer", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L136 5. Agent / AI Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "bb5af8c492df8f860d9b076eb120cb19c2d53b5399d5163fdf124aa936001932", "truncated": false}, "is_active": true}, {"id": "fd8d390f-4eda-5cc7-9d39-087c1f4bdf86", "feature_slug": "cs-knowledge-base", "title": "6b. For Marketing", "content": "**Value:** The knowledge base trains the brand''s AI voice. Product descriptions, FAQs, and policy documents feed directly into how the AI represents the brand to customers. Marketing controls brand accuracy by controlling what content exists in the knowledge base.\n\n**Use cases:**\n- **Product launches** — Upload product knowledge articles before launch day so the AI can answer questions from day one\n- **Campaign-specific FAQs** — Create custom answers for promotion-related questions (\"What''s the discount code?\" → exact answer) with `priority` set high so they override general knowledge\n- **Brand consistency** — The AI only knows what''s in the knowledge base. Keeping articles current ensures consistent messaging across all customer touchpoints\n- **Multi-language support** — Articles tagged by language enable the AI to respond in the customer''s language using localized content", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/cs-knowledge-base.md#L162 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-knowledge-base", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "54d60a6825c03be2c4b0cfef1d3e87d1591ee8194636a89509c9f0b1061dcd41", "truncated": false}, "is_active": true}, {"id": "bc45b21f-c4dd-51c3-bd0c-db8bbd245d54", "feature_slug": "cs-live-assist-feature-spec", "title": "6. LIVE ASSIST (Human Agent Augmentation)", "content": "### 6.1 AI-Drafted Replies\n\n- AI generates suggested reply based on conversation context and knowledge base\n- Agent sees the draft, can edit, approve, or discard\n- Multiple suggestions: AI offers 2-3 options with different tones or approaches\n- One-click send: approve and send without editing\n- Learning: track which drafts agents accept vs modify to improve quality\n\n### 6.2 Conversation Summary\n\n- When AI escalates to human, it generates a summary: what the customer wants, what was already tried, what data was collected\n- Running summary updates as conversation progresses\n- Summary available for supervisor review\n\n### 6.3 Knowledge Assist (Copilot Sidebar)\n\n- AI copilot available as a sidebar panel in the agent workspace (like Intercom''s Copilot)\n- Agent can ask the copilot questions in natural language: \"What''s our return policy for electronics?\" — copilot searches knowledge base and past conversations, returns the answer\n- Source filtering: agent selects which sources the copilot searches (internal articles only, public articles, past conversations, product docs)\n- Copilot cites sources: every answer includes links to the knowledge articles or past conversations it used\n- Agent can insert copilot''s answer directly into the reply composer with one click\n- Suggested macros: copilot recommends relevant canned responses based on conversation intent\n- Internal Q&A: copilot can answer internal/operational questions (not just customer-facing) — \"What''s the escalation process for fraud cases?\"\n- Copilot learns from agent behavior: tracks which suggestions agents accept/modify/reject to improve over time\n\n### 6.4 Action Suggestions\n\n- AI recommends actions: \"This customer is asking for a refund on order #12345. The order was delivered 3 days ago. Refund is within policy. Click to process.\"\n- Agent clicks to execute, or modifies before executing\n- Reduces decision fatigue and ensures policy compliance\n\n### 6.5 Real-Time Translation\n\n- For multi-language support: customer writes in Thai, agent sees English translation alongside\n- Agent writes in English, AI translates to Thai before sending\n- Language detection is automatic", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_Live_Assist.md#L5 6. LIVE ASSIST (Human Agent Augmentation)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-live-assist-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "26677a1abc5ad1677a376607e8cf528d3d7ae0f6f2235f079793798135487c88", "truncated": false}, "is_active": true}, {"id": "14b50438-f3af-55ae-90cf-bc0a0eee6dfc", "feature_slug": "cs-live-assist-feature-spec", "title": "CS Live Assist (Feature Spec) Domain Reference", "content": "**Keywords:** ai_draft, suggested_reply, conversation_summary, knowledge_assist, copilot_sidebar, action_suggestion, real_time_translation\n**Source:** `CS_Live_Assist.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-live-assist-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-live-assist-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "68364d3fa6a5b19aee19e00b3b8165f89e6fca052d8e0a4ecc11b78306d9f372", "truncated": false}, "is_active": true}, {"id": "3e883ac6-c1a2-5c04-a386-bbb56d08ccd3", "feature_slug": "cs-phone-number-purchasing", "title": "DB Functions", "content": "### Backend (called by Edge Functions)\n\n| Function | Signature | Purpose |\n|---|---|---|\n| `cs_fn_upsert_phone_number` | `(p_merchant_id, p_credential_id, p_provider, p_phone_number, p_friendly_name, p_country_code, p_capabilities, p_provider_sid, p_channel_use, p_monthly_cost_cents, p_voice_webhook_configured, p_sms_webhook_configured)` | Insert or update phone number record. On existing phone_number: updates fields, resets status to active. Returns `{phone_id, was_created}`. |\n| `cs_fn_release_phone_number` | `(p_phone_id, p_merchant_id)` | Set status=''released'', released_at=now(), clear webhook flags. Requires active status + merchant match. Returns `{success, phone_number}`. |\n\n### BFF (called by admin panel)\n\n| Function | Signature | Purpose |\n|---|---|---|\n| `cs_bff_get_phone_numbers` | `()` | List all active numbers for merchant (any provider). Returns array with: id, provider, phone_number, friendly_name, country_code, capabilities, status, channel_use, monthly_cost_cents, webhook flags, purchased_at, credential_name, conversation_count. |\n| `cs_bff_get_phone_number_details` | `(p_phone_id)` | Single number with full details + 30-day conversation count + 30-day voice call count. |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Phone_Number_Purchasing.md#L118 DB Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-phone-number-purchasing", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f09a0c948ddc0535cb227f0449e034384f2cd25363b6255b257ab2d62c2a1ff0", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
